<p class="eyebrow">Account verification</p><h1>Identity verification</h1><?php if(!$required): ?><section class="card"><h2>Not required for withdrawals</h2><p>Your current Country Pack does not require identity verification before withdrawals.</p></section><?php elseif($submission&&$submission['status']==='APPROVED'): ?><section class="card success-state"><h2>Identity verified</h2><p>Your identity verification is approved for this Country Pack.</p></section><?php else: ?><section class="card"><p>Status: <strong><?= e($submission['status']??'NOT_STARTED') ?></strong></p><?php if(!empty($submission['rejection_reason'])):?><div class="alert error"><strong>Why this was rejected</strong><p><?= e($submission['rejection_reason']) ?></p></div><?php endif; ?><?php if(!empty($submission['resubmission_message'])):?><div class="alert warning"><strong>Update required</strong><p><?= e($submission['resubmission_message']) ?></p></div><?php endif; ?><p><?= nl2br(e($config['instructions']??'')) ?></p><form method="post" action="<?= e(route('dashboard.kyc.save')) ?>" enctype="multipart/form-data" class="form-stack"><?= app('csrf')->input() ?><?php require __DIR__.'/../components/dynamic-form.php'; ?><div class="button-row"><button class="button button-secondary" name="submit" value="0">Save draft</button><button class="button" name="submit" value="1">Submit for review</button></div></form></section><?php endif; ?>
